"""Low-level dictionary and list hierarchy merger."""
from typing import Dict, Any, List

def _merge_lists_deduplicated(base_list: List[Any], override_list: List[Any]) -> List[Any]:
    """
    Concatenates two lists, removing duplicates while preserving first-seen order.
    Items from base_list are prioritized.
    """
    merged = []
    seen = set()

    for item in base_list:
        if item not in seen:
            merged.append(item)
            seen.add(item)

    for item in override_list:
        if item not in seen:
            merged.append(item)
            seen.add(item)
    return merged

def merge_spec_values(base: Dict[str, Any], override: Dict[str, Any]) -> Dict[str, Any]:
    """Recursively merges dictionary values."""
    result = dict(base)
    for k, v in override.items():
        if k in result and isinstance(result[k], dict) and isinstance(v, dict):
            result[k] = merge_spec_values(result[k], v)
        elif k in result and isinstance(result[k], list) and isinstance(v, list):
            result[k] = _merge_lists_deduplicated(result[k], v)
        else:
            result[k] = v
    return result

def is_spec_empty(spec: Dict[str, Any]) -> bool:
    return len(spec) == 0
